css:
:root {
  --bg: #f5f5f5;
  --surface: #ffffff;
  --border: #dddddd;
  --text: #111111;
  --text-medium: #333333;
  --text-muted: #666666;
  --text-ghost: #999999;
}
:root.dark {
  --bg: #0d0d0d;
  --surface: #161616;
  --border: #2a2a2a;
  --text: #eeeeee;
  --text-medium: #cccccc;
  --text-muted: #999999;
  --text-ghost: #666666;
}
.card-tile { border: 1px solid var(--border); border-radius: 8px; }
.card-tag { background: var(--text); color: var(--bg); }
